// Some portions generated by Claude
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');

const { createQueryBrowserHarness } = require('./query-browser-harness.js');

const HREF = 'http://localhost:8080/rdf4j-workbench/repositories/test/query';
const STORAGE_KEY = 'rdf4j.workbench.query.tabs.v1:test-session:test';

function mapStorage() {
    const values = new Map();
    return {
        values,
        getItem: (key) => (values.has(key) ? values.get(key) : null),
        setItem: (key, value) => { values.set(key, String(value)); },
        removeItem: (key) => { values.delete(key); }
    };
}

function mount(options = {}) {
    const localStorage = options.localStorage || mapStorage();
    const harness = createQueryBrowserHarness(Object.assign({ href: HREF, query: '' }, options.harness || {},
        { window: Object.assign({ localStorage }, options.window || {}) }));
    harness.runPageLoad();
    return { harness, localStorage, query: harness.context.workbench.query };
}

function tabButtons(harness) {
    return harness.document.querySelectorAll('#query-tabs [role="tab"]');
}

function titles(harness) {
    return Array.from(tabButtons(harness), tab => tab.querySelector('.query-tabs__title').textContent);
}

function selectedTitle(harness) {
    const selected = tabButtons(harness).filter(tab => tab.getAttribute('aria-selected') === 'true');
    assert.equal(selected.length, 1, 'exactly one tab is selected');
    return selected[0].querySelector('.query-tabs__title').textContent;
}

test('mounting without stored tabs opens one tab holding the restored query and renders the row', () => {
    const { harness, query, localStorage } = mount({ harness: { query: 'SELECT * WHERE { ?s ?p ?o }' } });
    const state = query.getQueryTabsState();
    assert.equal(state.tabs.length, 1);
    assert.equal(state.tabs[0].query, 'SELECT * WHERE { ?s ?p ?o }');
    assert.equal(state.activeId, state.tabs[0].id);
    assert.deepEqual(titles(harness), ['SELECT * WHERE { ?s ?p ?o }']);
    assert.equal(selectedTitle(harness), 'SELECT * WHERE { ?s ?p ?o }');
    assert.ok(harness.document.querySelector('#query-tabs .query-tabs__new'), 'the + button is rendered');
    assert.ok(harness.document.querySelector('#query-tabs .query-tabs__menu-button'), 'the ⋯ button is rendered');
    assert.ok(localStorage.values.has(STORAGE_KEY), 'the tabs are persisted per server and repository');
});

test('the tabs and the active one survive a reload through localStorage', () => {
    const first = mount();
    first.query.newQueryTab();
    const editor = first.harness.yasqeState.instances.query;
    editor.setValue('ASK { ?s ?p ?o }');
    editor.triggerChange();
    assert.equal(first.query.getQueryTabsState().tabs.length, 2);
    assert.equal(titles(first.harness)[1], 'ASK { ?s ?p ?o }');

    const second = mount({ localStorage: first.localStorage });
    const state = second.query.getQueryTabsState();
    assert.equal(state.tabs.length, 2);
    assert.equal(state.activeId, state.tabs[1].id, 'the tab that was active stays active');
    assert.equal(second.query.getQueryValue(), 'ASK { ?s ?p ?o }', 'the editor shows the active tab');
    assert.equal(selectedTitle(second.harness), 'ASK { ?s ?p ?o }');
});

test('two browser pages on one repository keep their own tabs across a refresh (separate session copies)', () => {
    const localStorage = mapStorage();
    const sessionA = mapStorage();
    const sessionB = mapStorage();
    const pageA = mount({ localStorage, window: { sessionStorage: sessionA } });
    const pageB = mount({ localStorage, window: { sessionStorage: sessionB } });
    pageA.harness.yasqeState.instances.query.setValue('SELECT * WHERE { ?s ?p ?o } LIMIT 1');
    pageA.harness.yasqeState.instances.query.triggerChange();
    pageB.harness.yasqeState.instances.query.setValue('ASK { ?s ?p ?o }');
    pageB.harness.yasqeState.instances.query.triggerChange();

    const refreshedA = mount({ localStorage, window: { sessionStorage: sessionA } });
    assert.equal(refreshedA.query.getQueryValue(), 'SELECT * WHERE { ?s ?p ?o } LIMIT 1');
    const refreshedB = mount({ localStorage, window: { sessionStorage: sessionB } });
    assert.equal(refreshedB.query.getQueryValue(), 'ASK { ?s ?p ?o }');
});

test('a new tab is empty and active; typing renames it live and marks it edited', () => {
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}' } });
    query.newQueryTab();
    let state = query.getQueryTabsState();
    assert.equal(state.tabs.length, 2);
    assert.equal(query.getQueryValue(), '');
    assert.equal(selectedTitle(harness), 'Untitled query');
    assert.equal(harness.yasqeState.instances.query.focused, true, 'the editor takes focus');

    const editor = harness.yasqeState.instances.query;
    editor.setValue('PREFIX ex: <http://e/>\nSELECT ?x WHERE { ?x a ex:T }');
    editor.triggerChange();
    state = query.getQueryTabsState();
    const active = state.tabs.filter(tab => tab.id === state.activeId)[0];
    assert.equal(active.query, 'PREFIX ex: <http://e/>\nSELECT ?x WHERE { ?x a ex:T }');
    assert.equal(active.dirty, true);
    assert.equal(selectedTitle(harness), 'SELECT ?x WHERE { ?x a ex:T }');
    const selected = tabButtons(harness).filter(tab => tab.getAttribute('aria-selected') === 'true')[0];
    assert.ok(selected.classList.contains('is-dirty'));
    assert.ok(selected.querySelector('.query-tabs__title').classList.contains('query-tabs__title--derived'));
    assert.equal(state.tabs[0].query, 'SELECT 1 {}', 'the other tab keeps its text');
});

test('selecting a tab swaps the editor text and keeps the text of the tab that was left', () => {
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}' } });
    query.newQueryTab();
    const editor = harness.yasqeState.instances.query;
    editor.setValue('SELECT 2 {}');
    editor.triggerChange();
    editor.setValue('SELECT 2 {} LIMIT 5');
    editor.triggerChange();
    const [first, second] = query.getQueryTabsState().tabs;

    tabButtons(harness)[0].click();
    assert.equal(query.getQueryTabsState().activeId, first.id);
    assert.equal(query.getQueryValue(), 'SELECT 1 {}');
    assert.equal(query.getQueryTabsState().tabs[1].query, 'SELECT 2 {} LIMIT 5');
    assert.equal(second.dirty, true);

    query.selectQueryTab(second.id);
    assert.equal(query.getQueryValue(), 'SELECT 2 {} LIMIT 5');
    query.selectQueryTab('no-such-tab');
    assert.equal(query.getQueryTabsState().activeId, second.id, 'an unknown id changes nothing');
});

test('closing shows the neighbour; closing the last tab leaves one empty tab', () => {
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}' } });
    query.newQueryTab();
    harness.yasqeState.instances.query.setValue('SELECT 2 {}');
    harness.yasqeState.instances.query.triggerChange();
    query.newQueryTab();
    harness.yasqeState.instances.query.setValue('SELECT 3 {}');
    harness.yasqeState.instances.query.triggerChange();
    const [first, second, third] = query.getQueryTabsState().tabs;

    query.selectQueryTab(second.id);
    tabButtons(harness)[1].querySelector('.query-tabs__close').click();
    assert.equal(query.getQueryTabsState().activeId, third.id, 'closing the shown tab shows the one to its right');
    assert.equal(query.getQueryValue(), 'SELECT 3 {}');

    query.closeQueryTab(first.id);
    assert.equal(query.getQueryTabsState().activeId, third.id, 'closing a background tab leaves the shown one');
    assert.equal(query.getQueryValue(), 'SELECT 3 {}');

    query.closeQueryTab(third.id);
    const state = query.getQueryTabsState();
    assert.equal(state.tabs.length, 1);
    assert.equal(state.tabs[0].query, '');
    assert.equal(query.getQueryValue(), '');
    assert.equal(selectedTitle(harness), 'Untitled query');
});

