test('the row supports arrow keys and Delete, and the ⋯ menu lists every open query', () => {
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}' } });
    query.newQueryTab();
    harness.yasqeState.instances.query.setValue('SELECT 2 {}');
    harness.yasqeState.instances.query.triggerChange();
    const [first, second] = query.getQueryTabsState().tabs;
    const strip = harness.document.querySelector('#query-tabs .query-tabs__strip');
    strip.dispatchEvent({ type: 'keydown', key: 'ArrowLeft', target: tabButtons(harness)[1], preventDefault() {} });
    assert.equal(query.getQueryTabsState().activeId, first.id);
    strip.dispatchEvent({ type: 'keydown', key: 'End', target: tabButtons(harness)[0], preventDefault() {} });
    assert.equal(query.getQueryTabsState().activeId, second.id);

    const rows = harness.document.querySelectorAll('#query-tabs .query-tabs__menu-row');
    assert.equal(rows.length, 2);
    assert.ok(rows[1].classList.contains('is-active'));
    assert.equal(rows[0].querySelector('.query-tabs__menu-meta').textContent, 'Not run yet');
    rows[0].querySelector('.query-tabs__menu-select').click();
    assert.equal(query.getQueryTabsState().activeId, first.id);

    strip.dispatchEvent({ type: 'keydown', key: 'Delete', target: tabButtons(harness)[1], preventDefault() {} });
    assert.equal(query.getQueryTabsState().tabs.length, 1);
    assert.equal(query.getQueryValue(), 'SELECT 1 {}');
});

