// ---------------------------------------------------------------- per-tab results (ExecPlan M3)

/** A stand-in for the streamed result page: controllers that remember whether they hold rows or a request. */
function fakeResultPage() {
    let counter = 0;
    const calls = [];
    function controller() {
        counter += 1;
        return {
            name: 'c' + counter, result: false, active: false, disposed: false, adopted: 0, shelved: 0,
            hasResult() { return this.result; },
            hasActiveRequest() { return this.active; },
            shelve() { this.shelved += 1; },
            adopt() { this.adopted += 1; },
            dispose() { this.disposed = true; this.active = false; }
        };
    }
    const page = {
        calls,
        mounted: controller(),
        ownsForm() { return true; },
        submitExecution() {
            calls.push('submit');
            page.mounted.result = true;
            page.mounted.active = true;
            // As the real page: false means the browser must not post the form; the result streams in.
            return false;
        },
        hasActiveRequest() { return page.mounted.active; },
        detachController() {
            calls.push('detach ' + page.mounted.name);
            const leaving = page.mounted;
            leaving.shelve();
            page.mounted = controller();
            return leaving;
        },
        attachController(next) {
            calls.push('attach ' + (next ? next.name : 'none'));
            if (next) {
                next.adopt();
                page.mounted = next;
            } else {
                page.mounted = controller();
            }
        }
    };
    return page;
}

function summary(harness, detail) {
    harness.document.getElementById('query-output').dispatchEvent({ type: 'workbench:query-result-summary', detail });
}

function statusOf(tabButton) {
    if (tabButton.querySelector('.query-tabs__spinner')) return 'running';
    if (tabButton.querySelector('.query-tabs__dot--error')) return 'error';
    if (tabButton.querySelector('.query-tabs__dot--ready')) return 'ready';
    const badge = tabButton.querySelector('.query-tabs__badge');
    return badge ? 'badge:' + badge.textContent : 'none';
}

test('a finished result is kept with its tab, shown again when the tab is, and badged from what the tab remembers', () => {
    const page = fakeResultPage();
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}', workbench: { queryPage: page } } });
    harness.document.getElementById('action').value = 'exec';
    query.doSubmit();
    const first = page.mounted;
    assert.deepEqual(page.calls, ['submit']);
    assert.equal(statusOf(tabButtons(harness)[0]), 'running', 'the shown tab spins while its request is out');

    first.active = false;
    summary(harness, { rows: true, rowCount: 17, total: 17, complete: true, error: false });
    let [tab] = query.getQueryTabsState().tabs;
    assert.equal(tab.lastRun.status, 'done');
    assert.equal(tab.lastRun.total, 17);
    assert.equal(tab.dirty, false);
    assert.equal(statusOf(tabButtons(harness)[0]), 'badge:17');

    query.newQueryTab();
    assert.deepEqual(page.calls, ['submit', 'detach c1', 'attach none']);
    assert.equal(first.shelved, 1);
    assert.equal(first.disposed, false, 'a result with rows is kept, not dropped');
    assert.equal(harness.getProperty('query-results-count', 'hidden'), true, 'the Results badge is cleared for the empty tab');

    tabButtons(harness)[0].click();
    assert.equal(page.calls[page.calls.length - 1], 'attach c1', 'the kept result comes back with its tab');
    assert.equal(first.adopted, 1);
    assert.equal(page.mounted, first);
    assert.equal(harness.getProperty('query-results-count', 'hidden'), false);
    assert.equal(harness.getText('query-results-count'), '17');
    [tab] = query.getQueryTabsState().tabs;
    assert.equal(tab.lastRun.total, 17, 'switching tabs does not change the remembered run');
});

test('an empty controller is dropped on switch; closing a tab disposes its result; a failed run shows the error dot', () => {
    const page = fakeResultPage();
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}', workbench: { queryPage: page } } });
    const empty = page.mounted;
    query.newQueryTab();
    assert.equal(empty.disposed, true, 'a controller without rows or a request is not worth keeping');

    harness.document.getElementById('action').value = 'exec';
    query.doSubmit();
    const second = page.mounted;
    second.active = false;
    // A request the server refuses (HTTP 400) reports an error without ever completing.
    summary(harness, { rows: false, rowCount: 0, total: null, complete: false, error: true });
    const [, secondTab] = query.getQueryTabsState().tabs;
    assert.equal(secondTab.lastRun.status, 'error');
    assert.equal(statusOf(tabButtons(harness)[1]), 'error');

    const [firstTab] = query.getQueryTabsState().tabs;
    query.selectQueryTab(firstTab.id);
    assert.equal(second.disposed, false);
    query.closeQueryTab(secondTab.id);
    assert.equal(second.disposed, true, 'closing a background tab disposes its kept result');

    query.doSubmit();
    const third = page.mounted;
    query.closeQueryTab(firstTab.id);
    assert.equal(third.disposed, true, 'closing the shown tab disposes the result it shows');
    assert.equal(query.getQueryTabsState().tabs.length, 1);
    assert.equal(query.getQueryTabsState().tabs[0].query, '');
});

test('a query runs on in a background tab: spinner while running, a ready mark when done, the count once shown', () => {
    const page = fakeResultPage();
    const { harness, query } = mount({ harness: { query: 'SELECT 1 {}', workbench: { queryPage: page } } });
    harness.document.getElementById('action').value = 'exec';
    query.doSubmit();
    const running = page.mounted;
    query.newQueryTab();
    assert.equal(running.disposed, false, 'a running query is kept alive');
    assert.equal(statusOf(tabButtons(harness)[0]), 'running');
    assert.equal(statusOf(tabButtons(harness)[1]), 'none');

    running.active = false;
    harness.document.dispatchEvent({ type: 'workbench:query-activity' });
    assert.equal(statusOf(tabButtons(harness)[0]), 'ready');
    const [firstTab] = query.getQueryTabsState().tabs;
    assert.equal(firstTab.lastRun.status, 'ready');

    tabButtons(harness)[0].click();
    assert.equal(page.mounted, running);
    summary(harness, { rows: true, rowCount: 3, total: 3, complete: true, error: false });
    assert.equal(statusOf(tabButtons(harness)[0]), 'badge:3');
    assert.equal(harness.document.querySelector('#query-tabs .query-tabs__menu-meta').textContent, '3 rows');
});

test('at most six background results are kept; the oldest goes first, a running one last', () => {
    const page = fakeResultPage();
    const { harness, query } = mount({ harness: { query: 'SELECT 0 {}', workbench: { queryPage: page } } });
    const kept = [];
    harness.document.getElementById('action').value = 'exec';
    for (let i = 0; i < 8; i++) {
        query.doSubmit();
        kept.push(page.mounted);
        if (i > 0) {
            page.mounted.active = false;
        }
        query.newQueryTab();
        harness.yasqeState.instances.query.setValue('SELECT ' + (i + 1) + ' {}');
        harness.yasqeState.instances.query.triggerChange();
    }
    assert.equal(kept[0].disposed, false, 'the first result is still running, so it is kept');
    assert.equal(kept[1].disposed, true, 'the oldest finished result went first');
    assert.equal(kept[2].disposed, true);
    assert.equal(kept[3].disposed, false);
    assert.equal(kept.filter(controller => !controller.disposed).length, 6);
});
